 app.innerHTML=`<aside class="sidebar" aria-label="Main navigation"><div class="sidebar-brand"><a href="#home" class="brand" aria-label="Consumer Behavior Lab home">Z.</a><span class="brand-name">Consumer<br><strong>Behavior Lab</strong></span></div><button class="collapse-nav" data-action="collapse" aria-label="Toggle navigation labels" aria-expanded="${!journey.preferences.collapsed}">${icon('menu',18)}<span>Collapse menu</span></button><span class="nav-caption"></span><nav>${navItems.map(([key,art,label])=>`<a href="#${key}" data-nav="${key}" title="${label}">${icon(art)}<span>${label}</span>${key==='practice'?'<b id="nav-due">0</b>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><small id="sidebar-rewards"></small><button class="text-link auto-menu" data-action="ui-auto-nav">Automatic menu</button><button class="profile" data-action="settings" title="Notes & backups" aria-label="Notes & backups"><img src="assets/avatar.webp" alt=""><span><strong>Zin’s study space</strong><small>Notes &amp; backups</small></span>${icon('external',17)}</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><span id="route-name">Home</span><span class="desktop-only">/</span><span class="desktop-only muted">Consumer Behavior</span></div><div class="global-search"><label class="sr-only" for="global-query">Search concepts and chapters</label>${icon('search',19)}<input id="global-query" autocomplete="off" type="search" role="combobox" aria-autocomplete="list" aria-haspopup="dialog" placeholder="Search for concepts, chapters, or topics…" aria-controls="search-suggestions" aria-expanded="false"><kbd>/</kbd><div id="search-suggestions" class="search-suggestions" role="dialog" aria-label="Search suggestions" hidden></div></div><span class="header-level" id="header-level"></span><button class="icon-btn" data-action="theme" aria-label="Switch light or dark theme">${icon('sun',21)}</button></header><div id="storage-warning"></div><main id="main" tabindex="-1"></main><footer><span>Consumer Behavior Lab</span><button data-action="settings">Saved on this browser · Back up your progress ${icon('external',13)}</button></footer></div>`;
