function weekly(){return `<div class="week-days" aria-label="Learning activity over the last seven days">${weeklyActivity(journey).map(d=>`<div class="${d.active?'active':''}" aria-label="${d.day}: ${d.active?'activity recorded':'no recorded activity'}"><span>${new Intl.DateTimeFormat('en-GB',{weekday:'narrow',timeZone:'Asia/Bangkok'}).format(new Date(d.day+'T12:00Z'))}</span><i>${d.active?icon('check',14):'·'}</i></div>`).join('')}</div>`;}
